CREATE TABLE `reportes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `departamento_congreso_id` bigint unsigned NOT NULL,
  `solicitante` varchar(125) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `area_informatica_id` bigint unsigned NOT NULL,
  `categoria_id` bigint unsigned NOT NULL,
  `capturo_user_id` bigint unsigned NOT NULL,
  `tecnico_user_id` bigint DEFAULT NULL,
  `numero_copias` bigint DEFAULT NULL,
  `numero_inventario` varchar(125) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `evento_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `reportes_departamento_congreso_id_foreign` (`departamento_congreso_id`),
  KEY `reportes_area_informatica_id_foreign` (`area_informatica_id`),
  KEY `reportes_estado_id_foreign` (`estado_id`),
  KEY `reportes_evento_id_foreign` (`evento_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
